/// Screenshot fixture: the zone card for the fixture walk's mastered zone.
struct GoldieZoneCardPreview: View {
    @State private var completion: WorkoutZoneCompletion?

    var body: some View {
        Group {
            if let completion { WorkoutZoneCelebrationView(completion: completion) }
            else { Color.black.ignoresSafeArea() }
        }
        .task {
            guard let end = GoldieWalkFixture.route.last else { return }
            let zone = WorkoutHexGrid.key(end).district
            guard let streets = await WorkoutZoneStreets.shared.load(zone) else { return }
            let label = await WorkoutZoneNames.name(for: zone)
            let walked = WorkoutHexGrid.tiles(routes: GoldieWalkFixture.earlierWalks + [GoldieWalkFixture.route])
                .filter { $0.district == zone }
            completion = WorkoutZoneCompletion(zone: zone, name: label.name, area: label.area, streetTiles: streets,
                walkedTiles: walked, percent: 96.7, completedAt: Date(), ordinal: 3)
        }
    }
}
